"""Merchant hypothesis registry (28 hypotheses), expressed in the shared deterministic condition language.

Each hypothesis lists triggers (why it is worth considering), supporting conditions (evidence for it) and contradicting
conditions (evidence against it). The shared engine evaluates them against the merchant signals and computes the
Evidence Support Score; nothing here is random, scored by a model, or specific to one finding.
"""
from __future__ import annotations

from app.investigation.registry import Condition as C
from app.investigation.registry import HypothesisSpec as H

