SUPPLY = ("SUPPLIER_DELAY", "SUPPLIER_RELIABILITY")
DEMAND_DOWN = ("DEMAND_DECLINE",)
BUSINESS = ("REVENUE_DECLINE", "REPEAT_CUSTOMER_DECLINE")
OPP_ALL = ("DEMAND_OPPORTUNITY", "CATEGORY_OPPORTUNITY", "REGIONAL_OPPORTUNITY")

